/*
 * A225524  G.f.: exp( Sum_{n>=1} (sigma(2*n) - sigma(n))*Lucas(n)*x^n/n ),
 *          where Lucas(n) = A000204(n) and sigma(n) = A000203(n) is the sum
 *          of divisors of n.
 * https://oeis.org/A225524
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (1/n) * Σ_{k=1}^{n} b(k) * a(n-k) (n≥1), with * a(0)=1,
 *            b(k) = (σ(2k)−σ(k)) * Lucas(k). Here σ(m) is the sum of divisors
 *            of m * and Lucas(m) is the m‑th Lucas number. The series is
 *            generated by * a(x) = exp( Σ_{k≥1} (σ(2k)−σ(k))*Lucas(k)*x^k/k )
 * Range:     u8 n <= 3, u16 n <= 8, u32 n <= 21, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n) {
    static idx_t max_n = 0;
    static seq_t *sigma = NULL;   /* Σ up to 2*max_n  */
    static seq_t *lucas = NULL;   /* up to max_n */
    static seq_t *bcoef = NULL;   /* b(k) 1..max_n */
    static seq_t *aseq  = NULL;   /* a(0)..a(max_n) */

    if (n == 0) /* a(0)=1 */
        return (seq_t)1;

    /* Expand to required size */
    if (n > max_n) {
        idx_t new_n = n;
        size_t sz_sigma = (size_t)(2*new_n + 1);
        size_t sz_lucas = (size_t)(new_n + 1);
        size_t sz_b     = (size_t)(new_n + 1);
        size_t sz_a     = (size_t)(new_n + 1);

        /* Resize and recompute sigma (sum of divisors) */
        sigma = (seq_t*)realloc(sigma, sz_sigma * sizeof(seq_t));
        for (size_t i = 0; i < sz_sigma; ++i) sigma[i] = 0;
        for (idx_t i = 1; i <= 2*new_n; ++i) {
            for (idx_t j = i; j <= 2*new_n; j += i)
                sigma[j] += (seq_t)i;
        }

        /* Resize and compute Lucas numbers */
        lucas = (seq_t*)realloc(lucas, sz_lucas * sizeof(seq_t));
        lucas[0] = (seq_t)2;
        if (new_n >= 1) lucas[1] = (seq_t)1;
        for (idx_t i = 2; i <= new_n; ++i)
            lucas[i] = lucas[i-1] + lucas[i-2];

        /* Resize and compute coefficient b(k) */
        bcoef = (seq_t*)realloc(bcoef, sz_b * sizeof(seq_t));
        for (idx_t k = 1; k <= new_n; ++k) {
            seq_t diff  = sigma[2*k] - sigma[k];
            bcoef[k] = diff * lucas[k];
        }

        /* Resize and compute a(n) by recurrence */
        aseq = (seq_t*)realloc(aseq, sz_a * sizeof(seq_t));
        aseq[0] = (seq_t)1;
        for (idx_t i = 1; i <= new_n; ++i) {
            seq_t sum = 0;
            for (idx_t k = 1; k <= i; ++k) {
                sum += aseq[i-k] * bcoef[k];
            }
            aseq[i] = sum / (seq_t)i;   /* division is exact */
        }

        max_n = new_n;
    }
    return aseq[n];
}
